require dirname(__DIR__).'/private/bootstrap.php';session_init();header('Cache-Control: no-store');header('Content-Security-Policy: default-src \'self\'; style-src \'self\' \'unsafe-inline\'; form-action \'self\'; frame-ancestors \'none\'');
$_SESSION['csrf']??=bin2hex(random_bytes(24));$credentials=__DIR__.'/../private/credentials.json';$setup=!is_file($credentials);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 origin_guard();if(!hash_equals($_SESSION['csrf'],$_POST['csrf']??''))fail('Invalid form.',403);$password=$_POST['password']??'';
 $f=fopen(__DIR__.'/../private/login-attempts.json','c+');flock($f,LOCK_EX);$raw=stream_get_contents($f);$attempts=$raw?json_decode($raw,true):[];$key=hash('sha256',$_SERVER['REMOTE_ADDR']??'unknown');$a=$attempts[$key]??['time'=>time(),'count'=>0];if(time()-$a['time']>900)$a=['time'=>time(),'count'=>0];$ok=false;
 if($a['count']>=5)$error='Too many attempts. Try again in 15 minutes.';
 elseif($setup){$token=config()['setup_token']??'';if(strlen($token)<24||!hash_equals($token,$_POST['token']??''))$error='Set a setup token of at least 24 characters in private/config.php, then enter it here.';elseif(strlen($password)<14)$error='Choose a password of at least 14 characters.';else{$handle=fopen($credentials,'x');if(!$handle)$error='Owner already configured. Reload to sign in.';else{fwrite($handle,json_encode(['hash'=>password_hash($password,PASSWORD_DEFAULT)]));fclose($handle);chmod($credentials,0600);$ok=true;}}}
 else{$c=json_decode(file_get_contents($credentials),true);$ok=password_verify($password,$c['hash']);if(!$ok)$error='Incorrect password.';}
 $attempts[$key]=$ok?['time'=>time(),'count'=>0]:['time'=>$a['time'],'count'=>$a['count']+1];foreach($attempts as $k=>$v)if(time()-$v['time']>900)unset($attempts[$k]);$json=json_encode($attempts);rewind($f);fwrite($f,$json);ftruncate($f,strlen($json));flock($f,LOCK_UN);fclose($f);
 if($ok){session_regenerate_id(true);$_SESSION['owner']=true;$next=$_GET['next']??'/editor';header('Location: '.(in_array($next,['/editor','/admin'],true)?$next:'/editor'));exit;}
}
